export function variantMarkup(markup,base,mode){
 if(overlayBatch.some(item=>item.base===base))return overlayMarkup(markup,base,mode);
 if(navigationBatch.some(item=>item.base===base))return navigationMarkup(markup,base,mode);
 if(sliderBatch.some(item=>item.base===base))return sliderMarkup(markup,base,mode);
 if(toggleBatch.some(item=>item.base===base))return toggleMarkup(markup,base,mode);
 if(checkboxBatch.some(item=>item.base===base))return checkboxMarkup(markup,base,mode);
 if(menuBatch.some(item=>item.base===base))return menuMarkup(markup,base,mode);
 if(base==='search-input'||base==='password-input'||base.startsWith('inputs-'))return inputMarkup(markup,base,mode);
 const className='sl-variant-'+mode;
 if(base.startsWith('buttons-')){
  let result=markup.replace('class="sl-component"',`class="sl-component ${className}"`);
  if(base.startsWith('buttons-everyday-buttons-'))return result;
  if(/^buttons-(close-item|open-external|read-toggle|flag-toggle|snooze-toggle|publish-toggle|sync-toggle|report-toggle|power-toggle|group-toggle)-v11$/.test(base))return result;
  if(/^buttons-(cart-toggle|archive-toggle|task-complete|assign-toggle|compare-toggle|new-folder|comment-toggle|translate-toggle|tag-toggle|photo-toggle)-v11$/.test(base))return result;
  if(/^buttons-(text-editor|image-transform)-toolbar-v11$/.test(base)){
   const labels={bold:'Bold',italic:'Italic',case:'Case',strike:'Strike',align:'Align',list:'List',indent:'Indent',rotate:'Rotate',mirror:'Mirror'};
   return result.replace(/(<button\b[^>]*data-command="([a-z]+)"[^>]*>)([\s\S]*?)(<\/button>)/g,(_all,open,command,inside,close)=>open+inside.replace(/<\/span>((?:\s|\\[nr])*)$/,(_end,space)=>`<span class="tool-label">${labels[command]}</span></span>`+space)+close);
  }
  if(/^buttons-(expand-toggle|view-switch|sidebar-toggle|notifications-toggle|attachment-toggle|undo-action|move-item|crop-mode)-v11$/.test(base))return result;
  if(/^buttons-(link-toggle|lock-toggle|details-disclosure|filter-toggle|sort-direction|pin-toggle|print-document|search-toggle|visibility-toggle|zoom-view)-v11$/.test(base))return result;
  if(base==='buttons-repeat-stepper-v11')return result.replace(/(<button[^>]+data-(minus|plus)[^>]*>)([\s\S]*?)(<\/button>)/g,(_all,open,action,inside,close)=>open+inside+`<span class="presentation-label">${action==='minus'?'Less':'More'}</span>`+close);
  // Preserve controller-owned label spans. Only wrap literal button captions,
  // so dynamic labels and accessible names keep tracking the actual action.
  return result.replace(/(<button\b[^>]*>)([\s\S]*?)(<\/button>)/g,(_all,open,inside,close)=>{
   if(!/<svg\b/.test(inside)||/data-remove/.test(open)||/motion-button/.test(open))return open+inside+close;
   open=open.replace('>', ' data-presentation-action>');
   inside=inside.replace(/(<\/svg>)([^<]+)$/,(_tail,svg,label)=>svg+`<span class="presentation-label">${label}</span>`);
   return open+inside+close;
  });
 }
 let result=markup.replace(`class="sl-${base}"`,`class="sl-${base} ${className}"`);
 if(base==='share')result=result.replace('class="sl-share-control"',`class="sl-share-control ${className}"`);
 return result;
}